@GameTestHolder(SevenfoldMastery.ID) @PrefixGameTestTemplate(false)
public final class MasteryTests {
    private static FakePlayer player(GameTestHelper h){return new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"TenStarTest"));}
    private static StarTreeState root(){return new StarTreeState(0).toggle(StarNode.CRYING,0);}
    private static StarTreeState complete(StarTreeState s,StarNode n){if(!s.isActivated(n))s=s.toggle(n,StarTreeState.CONSTELLATION);for(int i=0;i<10;i++)if(!s.star(n,i))s=s.toggle(n,i);return s;}
    @GameTest(template="empty") public static void soundTailsOverlapWithoutCuttingOrRestartingRelease(GameTestHelper h){
        var old=new com.muxigame.sevenfold.ui.TreeSoundFade(0,180);old.fade(1000,1500);var fresh=new com.muxigame.sevenfold.ui.TreeSoundFade(1000,220);
        h.assertTrue(old.value(1000)==1&&fresh.value(1000)==0,"Previous voice begins release at its current gain, new voice has no hard onset");
        h.assertTrue(old.value(1220)>.9&&fresh.value(1220)==1&&old.value(1750)==.5,"Old tail and new sound overlap; old tail remains audible at the midpoint");
        double before=old.value(1800);old.fade(1800,1500);h.assertTrue(old.value(1800)==before&&old.finished(2500)&&old.value(2500)==0,"Repeated events cannot restart release or leave stale voices alive");h.succeed();
    }
    @GameTest(template="empty") public static void interruptedSoundAttackKeepsContinuousGain(GameTestHelper h){
        var f=new com.muxigame.sevenfold.ui.TreeSoundFade(100,200);double before=f.value(200);f.fade(200,1500);
        h.assertTrue(before==.5&&f.value(200)==before&&f.value(950)==.25,"Interrupting an incoming voice retains its current level and fades the remaining tail");
        h.assertTrue(!f.finished(1699)&&f.finished(1700)&&f.value(1700)==0,"Release completes exactly without an early silence gate");h.succeed();
    }
    @GameTest(template="empty") public static void confirmedExtinctionAudioIsDistinctAndBootstrapQuiet(GameTestHelper h){
        var full=complete(root(),StarNode.WARRIOR);var change=com.muxigame.sevenfold.ui.TreeAudioChange.between(null,full);
        h.assertTrue(!change.ignition()&&!change.extinction(),"Loading an already lit save plays neither confirmation cue");
        var off=full.toggle(StarNode.WARRIOR,2);change=com.muxigame.sevenfold.ui.TreeAudioChange.between(full,off);
        h.assertTrue(change.extinction()&&!change.ignition()&&!change.majorExtinction(),"One confirmed star loss uses only the small descending cue");
        change=com.muxigame.sevenfold.ui.TreeAudioChange.between(off,StarTreeState.load(off.save()));h.assertTrue(!change.ignition()&&!change.extinction(),"Duplicate server snapshots do not repeat the sound");
        change=com.muxigame.sevenfold.ui.TreeAudioChange.between(off,full);h.assertTrue(change.ignition()&&!change.extinction()&&change.majorIgnition(),"Relight has a separate cue and recognizes completed constellations");h.succeed();
    }
    @GameTest(template="empty") public static void extinctionAudioAggregatesCascadeAndEmptyActivation(GameTestHelper h){
        var full=complete(complete(root(),StarNode.WARRIOR),StarNode.KNIGHT);var off=full.toggle(StarNode.CRYING,-1);var change=com.muxigame.sevenfold.ui.TreeAudioChange.between(full,off);
        h.assertTrue(change.extinction()&&change.majorExtinction()&&!change.ignition(),"Departure plus multiple dependent constellations produces one aggregated extinction decision");
        var empty=root().toggle(StarNode.WARRIOR,-1);change=com.muxigame.sevenfold.ui.TreeAudioChange.between(empty,empty.toggle(StarNode.WARRIOR,-1));
        h.assertTrue(change.extinction()&&change.majorExtinction()&&!change.ignition(),"Closing an activated zero-star constellation still has a sound");
        change=com.muxigame.sevenfold.ui.TreeAudioChange.between(full,full.toggle(StarNode.MAGE,-1));
        h.assertTrue(change.extinction()&&change.ignition()&&change.majorExtinction(),"Switching paths distinguishes the old dying path from the new activation without per-star sound spam");h.succeed();
    }
    @GameTest(template="empty") public static void extinctionFadesSingleStarsWithoutDelayingState(GameTestHelper h){
        var s=complete(root(),StarNode.WARRIOR);var light=new com.muxigame.sevenfold.ui.TreeLight();light.update(s,100);
        h.assertTrue(light.star(StarNode.WARRIOR,0,100)==1&&light.extinction(StarNode.WARRIOR,0,100)<0,"Loading a lit save does not replay animation");
        s=s.toggle(StarNode.WARRIOR,0);light.update(s,200);
        h.assertTrue(!s.star(StarNode.WARRIOR,0)&&light.star(StarNode.WARRIOR,0,200)==1,"Gameplay changes immediately; presentation begins at the previous brightness");
        light.update(s,750);h.assertTrue(light.star(StarNode.WARRIOR,0,750)==.5&&light.star(StarNode.WARRIOR,1,750)==1,"Unchanged sync cannot restart fading or darken other stars");
        h.assertTrue(light.star(StarNode.WARRIOR,0,1300)==0&&light.extinction(StarNode.WARRIOR,0,1300)<0&&light.active(StarNode.WARRIOR,1300)==1,"A single extinction settles exactly, retaining constellation activation");h.succeed();
    }
    @GameTest(template="empty") public static void extinctionKeepsLostBranchesVisibleUntilMistReturns(GameTestHelper h){
        var s=complete(complete(root(),StarNode.WARRIOR),StarNode.KNIGHT);var light=new com.muxigame.sevenfold.ui.TreeLight();light.update(s,100);
        s=s.toggle(StarNode.WARRIOR,StarTreeState.CONSTELLATION);light.update(s,200);
        h.assertTrue(!s.visible(StarNode.KNIGHT)&&s.profession()==WarProfession.NONE&&light.visible(StarNode.KNIGHT,200)==1,"Lost branch is immediately unavailable but retained for visual fade");
        h.assertTrue(light.visible(StarNode.KNIGHT,950)==.5&&light.active(StarNode.WARRIOR,675)==.5,"Branch silhouettes and active glow fade independently");
        h.assertTrue(light.visible(StarNode.KNIGHT,1700)==0&&light.active(StarNode.CRYING,1700)==1,"Only dependent branch disappears; Departure remains lit");
        s=s.toggle(StarNode.CRYING,StarTreeState.CONSTELLATION);light.update(s,1800);
        h.assertTrue(light.active(StarNode.CRYING,1800)==1&&light.visible(StarNode.WARRIOR,1800)==1&&light.visible(StarNode.WARRIOR,3300)==0,"Departure extinction also fades trunk and revealed main constellations");h.succeed();
    }
    @GameTest(template="empty") public static void extinctionReversesContinuouslyAndBootstrapStaysQuiet(GameTestHelper h){
        for(var n:StarNode.BASES){var s=complete(root(),n);var light=new com.muxigame.sevenfold.ui.TreeLight();light.update(s,0);var off=s.toggle(n,0);light.update(off,100);double before=light.star(n,0,650);light.update(s,650);
            h.assertTrue(light.star(n,0,650)==before&&light.extinction(n,0,650)<0&&light.star(n,0,970)==1,"Rapid relight reverses from current brightness for every main color");
            light.reset();light.update(off,2000);h.assertTrue(light.star(n,0,2000)==0&&light.extinction(n,0,2000)<0,"Reopening a dark save creates no stray extinction particles");}
        h.succeed();
    }
    @GameTest(template="empty") public static void constellationZoomAcceleratesThenSettlesAndReverses(GameTestHelper h){
        var z=new com.muxigame.sevenfold.ui.TreeZoom();z.towards(true,0);double a=z.value(90),b=z.value(180),c=z.value(270);
        h.assertTrue(a>0&&b-a>a&&c-b>b-a,"Approach begins gently and accelerates rather than snapping to full scale");
        double peak=0;for(int i=0;i<900;i+=10)peak=Math.max(peak,z.value(i));h.assertTrue(peak>1&&peak<1.03&&z.value(900)==1&&!z.moving(900),"Small inertial overshoot settles exactly at the existing detail layout");
        z.towards(false,1000);double before=z.value(1200);z.towards(true,1200);h.assertTrue(z.value(1200)==before&&z.value(2100)==1,"Interrupting retreat preserves the visible camera position");
        z.towards(false,2200);z.towards(false,2400);h.assertTrue(z.value(3100)==0&&!z.moving(3100),"Retreat reaches original overview; repeat input cannot extend the transition");h.succeed();
    }
    @GameTest(template="empty") public static void zoomProjectionPreservesBothExistingInformationLayouts(GameTestHelper h){
        for(var n:StarNode.values())if(n!=StarNode.RESET)for(var xy:n.pattern())for(int compact=0;compact<2;compact++){
            int w=compact==0?640:427,ht=compact==0?360:240;double scale=com.muxigame.sevenfold.ui.TreeLayout.scale(w,ht);var origin=com.muxigame.sevenfold.ui.TreeLayout.position(n);
            double ox=w*.5+origin.x()*scale,oy=ht*.42-Math.max(0,300-ht)*.3+origin.y()*scale;
            double detail=Math.min(w*.34,Math.max(44,(ht-80)*.65)),perspective=1/(1+(1-xy[1])*.10);
            double wx=ox+(xy[0]+xy[1]*.14)*18*perspective,wy=oy+xy[1]*18*.66*perspective;
            double px=com.muxigame.sevenfold.ui.TreeZoom.project(wx,ox,w*.5,detail/18,1),py=com.muxigame.sevenfold.ui.TreeZoom.project(wy,oy,ht*.55,detail/18,1);
            h.assertTrue(Math.abs(px-(w*.5+(xy[0]+xy[1]*.14)*detail*perspective))<.000001&&Math.abs(py-(ht*.55+xy[1]*detail*.66*perspective))<.000001,"Every existing star reaches its original detail coordinates at both GUI sizes");
            h.assertTrue(Math.abs(com.muxigame.sevenfold.ui.TreeZoom.project(wx,ox,w*.5,detail/18,0)-wx)<.000001&&Math.abs(com.muxigame.sevenfold.ui.TreeZoom.project(wy,oy,ht*.55,detail/18,0)-wy)<.000001,"Overview endpoint retains every original star coordinate");
        }h.succeed();
    }
    @GameTest(template="empty") public static void lowerEdgeCanBringUpperCareersBackBeforeReturning(GameTestHelper h){
        var c=new com.muxigame.sevenfold.ui.TreeCamera();c.bounds(-300,300,-300,0);for(int i=0;i<25;i++)c.update(320,1,640,360,.05,true);
        h.assertTrue(c.y()<-100&&!com.muxigame.sevenfold.ui.TreeReturnEdge.available(c.y(),false),"Upward browse makes bottom edge pan back, not exit");
        for(int i=0;i<100;i++)c.update(320,359,640,360,.05,true);
        h.assertTrue(c.y()==0&&com.muxigame.sevenfold.ui.TreeReturnEdge.available(c.y(),false),"Bottom smoothly returns to origin, then becomes return gesture without overshoot");
        h.assertTrue(com.muxigame.sevenfold.ui.TreeReturnEdge.available(-200,true),"An open overlay can always be dismissed");h.succeed();
    }
    @GameTest(template="empty") public static void cameraPassageCompletesAndReversesWithoutJump(GameTestHelper h){
        var p=new com.muxigame.sevenfold.ui.TreePassage();p.open(0);h.assertTrue(p.sky(0)==0&&!p.interactive(999)&&p.sky(500)==.5&&p.sky(1000)==1&&p.interactive(1000),"Inventory-to-sky lift lasts one second and blocks moving target actions");
        p.close(1500);p.close(1800);h.assertTrue(p.sky(1500)==1&&p.sky(2000)==.5&&!p.finished(2499)&&p.finished(2500)&&p.sky(2500)==0,"Return is one second, repeat close cannot restart it");
        var q=new com.muxigame.sevenfold.ui.TreePassage();q.open(0);double before=q.sky(400);q.close(400);h.assertTrue(q.sky(400)==before&&q.sky(900)<before&&q.finished(1400),"Closing during entry continues from actual visual position without a snap");h.succeed();
    }
    @GameTest(template="empty") public static void returnEdgeFadesTogetherInOneSecondOutWithinHalf(GameTestHelper h){
        var f=new com.muxigame.sevenfold.ui.TreeReturnEdge();for(int i=0;i<10;i++)f.update(true,.05);h.assertTrue(Math.abs(f.opacity()-.5)<.0001,"Arrow and veil share the same eased half-fade at0.5s");
        for(int i=0;i<10;i++)f.update(true,.05);h.assertTrue(f.opacity()==1,"Fully visible at1s, never pops in");for(int i=0;i<5;i++)f.update(false,.05);h.assertTrue(Math.abs(f.opacity()-.5)<.0001,"Half-faded after0.25s away");for(int i=0;i<5;i++)f.update(false,.05);h.assertTrue(f.opacity()<.0001,"Gone within0.5s; both symbols use this opacity");
        f.update(true,.2);double partial=f.opacity();f.update(false,.05);h.assertTrue(f.opacity()>0&&f.opacity()<partial,"Leaving during entrance reverses without a brightness jump");f.reset();h.assertTrue(f.opacity()==0,"Page transitions clear return feedback");h.succeed();
    }
    @GameTest(template="empty") public static void bottomReturnRegionIsLowAndNeverPansDown(GameTestHelper h){
        h.assertTrue(com.muxigame.sevenfold.ui.TreeReturnEdge.height(360)==23&&com.muxigame.sevenfold.ui.TreeReturnEdge.height(1080)==24,"Return mist stays shallow at all sizes");
        h.assertTrue(com.muxigame.sevenfold.ui.TreeReturnEdge.contains(320,359,640,360)&&!com.muxigame.sevenfold.ui.TreeReturnEdge.contains(320,336,640,360)&&!com.muxigame.sevenfold.ui.TreeReturnEdge.contains(320,360,640,360),"Only the low in-window region is a return target");
        var c=new com.muxigame.sevenfold.ui.TreeCamera();c.bounds(-500,500,-500,0);for(int i=0;i<100;i++)c.update(320,359,640,360,.05,true);h.assertTrue(c.y()==0&&c.speed()==0,"Bottom edge cannot browse empty space below the origin");c.update(320,1,640,360,.05,true);h.assertTrue(c.y()<0,"Upper career branches remain browsable");double y=c.y();c.update(320,359,640,360,.05,false);h.assertTrue(c.y()==y&&c.speed()==0,"Return region immediately freezes inherited motion");h.succeed();
    }
    @GameTest(template="empty") public static void retiredMasteryLegacyMigrationPreservesRawHistory(GameTestHelper h){
        var p=player(h);var old=new CompoundTag();old.putInt("schema",3);old.putString("mastery","stamina");old.putInt("resource",11);old.putString("extra_history","preserve");p.getPersistentData().put(MasteryState.KEY,old.copy());
        var migrated=CombatPools.of(p);h.assertTrue(migrated.stamina()==11&&migrated.mana()==20,"Early saves migrate the spent reserve once without inventing an elemental choice");migrated.store(p);
        var clone=player(h);MasteryState.copyLegacy(p,clone);h.assertTrue(clone.getPersistentData().getCompound(MasteryState.KEY).equals(old)&&p.getPersistentData().getCompound(MasteryState.KEY).equals(old),"Legacy raw history survives clone without schema rewrite");
        clone.getPersistentData().getCompound(MasteryState.KEY).putInt("resource",1);h.assertTrue(p.getPersistentData().getCompound(MasteryState.KEY).getInt("resource")==11,"Clone does not alias original legacy NBT");h.succeed();
    }
    @GameTest(template="empty") public static void retiredMasteryPacketsCannotSelectOrAlterResources(GameTestHelper h){
        var p=player(h);SevenfoldMastery.applyStars(p,complete(root(),StarNode.WARRIOR));
        new MasteryState(Mastery.THUNDER,17).store(p);new CombatPools(13,29,31,7,41,5).store(p);
        var old=p.getPersistentData().getCompound(MasteryState.KEY).copy();var pools=CombatPools.of(p);var stars=StarTreeState.of(p);
        SevenfoldMastery.action(p,new MasteryNetwork.Action("begin","might"));
        SevenfoldMastery.action(p,new MasteryNetwork.Action("finish","might"));
        h.assertTrue(old.equals(p.getPersistentData().getCompound(MasteryState.KEY))&&pools.equals(CombatPools.of(p))&&stars.equals(StarTreeState.of(p)),"Retired selector cannot mutate legacy data, resource reserves or earned stars");
        h.assertTrue(CombatPools.displayedResource(stars)==null&&CombatPools.of(p).mana()==41,"Saved elemental selection has no HUD effect; neutral mana remains independent");h.succeed();
    }
    @GameTest(template="empty") public static void displayedResourceFollowsCompletedProfessionOnly(GameTestHelper h){
        var base=complete(root(),StarNode.WARRIOR);var nodes=new StarNode[]{StarNode.BERSERKER,StarNode.WARDEN,StarNode.KNIGHT,StarNode.BRAWLER};var resources=new Mastery[]{Mastery.MIGHT,Mastery.STAMINA,Mastery.RESILIENCE,Mastery.FOCUS};
        for(int j=0;j<nodes.length;j++){var full=complete(base,nodes[j]);h.assertTrue(CombatPools.displayedResource(full)==resources[j],"Each completed profession displays its own existing resource");h.assertTrue(CombatPools.displayedResource(full.toggle(nodes[j],4))==null,"Incomplete profession returns to mana without a separate mastery");}
        h.assertTrue(CombatPools.displayedResource(root())==null&&CombatPools.displayedResource(complete(root(),StarNode.MAGE))==null&&CombatPools.displayedResource(complete(root(),StarNode.ASSASSIN))==null,"Root and unimplemented paths use neutral mana");h.succeed();
    }
    @GameTest(template="empty") public static void departureLightsAllTenAtOnce(GameTestHelper h){var s=new StarTreeState(0).toggle(StarNode.CRYING,7);h.assertTrue(s.active()&&s.count(StarNode.CRYING)==10,"Departure activates entire constellation");h.assertTrue(s.toggle(StarNode.CRYING,3).equals(new StarTreeState(0)),"Deactivation closes all ten");h.succeed();}
    @GameTest(template="empty") public static void individualStarsHaveNoTrackOrder(GameTestHelper h){var s=root().toggle(StarNode.WARRIOR,-1).toggle(StarNode.WARRIOR,9).toggle(StarNode.WARRIOR,2);h.assertTrue(s.count(StarNode.WARRIOR)==2&&s.star(StarNode.WARRIOR,9),"Any individual star may be chosen first after deliberate activation");h.assertFalse(s.canToggle(StarNode.KNIGHT,0),"Ten main stars required");h.succeed();}
    @GameTest(template="empty") public static void professionWaitsForAllTenStars(GameTestHelper h){var s=complete(root(),StarNode.WARRIOR).toggle(StarNode.KNIGHT,-1);for(int i=0;i<9;i++)s=s.toggle(StarNode.KNIGHT,i);h.assertTrue(s.profession()==WarProfession.NONE,"Nine stars provide no professional effect");s=s.toggle(StarNode.KNIGHT,9);h.assertTrue(s.profession()==WarProfession.KNIGHT,"Tenth star enables profession");s=s.toggle(StarNode.KNIGHT,4);h.assertTrue(s.profession()==WarProfession.NONE&&s.count(StarNode.KNIGHT)==9,"Removing one disables effect immediately");h.succeed();}
    @GameTest(template="empty") public static void onlyOneDestinyAndSpecialization(GameTestHelper h){var s=complete(complete(root(),StarNode.WARRIOR),StarNode.BERSERKER).toggle(StarNode.WARDEN,-1).toggle(StarNode.WARDEN,2);h.assertTrue(s.count(StarNode.BERSERKER)==0&&s.count(StarNode.WARDEN)==1&&s.profession()==WarProfession.NONE,"No simultaneous profession benefits");s=s.toggle(StarNode.ASSASSIN,-1).toggle(StarNode.ASSASSIN,7);h.assertTrue(s.path()==StarNode.ASSASSIN&&s.count(StarNode.WARRIOR)==0&&s.count(StarNode.WARDEN)==0,"Changing destiny clears old branch");h.succeed();}
    @GameTest(template="empty") public static void incompleteParentClosesDependentConstellations(GameTestHelper h){var s=complete(complete(root(),StarNode.WARRIOR),StarNode.BRAWLER).toggle(StarNode.WARRIOR,8);h.assertTrue(s.count(StarNode.WARRIOR)==9&&s.count(StarNode.BRAWLER)==0,"Parent completeness gates advanced branch");h.succeed();}
    @GameTest(template="empty") public static void blessingsWaitForUserDesign(GameTestHelper h){var s=complete(complete(root(),StarNode.WARRIOR),StarNode.KNIGHT);h.assertTrue(s.healthBonus()==100&&s.manaBonus()==80&&s.attackBonus()==0,"War grants20 health; advanced/Cunning/Reason blessings remain unassigned");h.assertTrue(s.reset().equals(root()),"Reset keeps Departure");h.succeed();}
    @GameTest(template="empty") public static void saveLoadAndMalformedIsolation(GameTestHelper h){var s=complete(root(),StarNode.ASSASSIN).toggle(StarNode.ASSASSIN,3);h.assertTrue(StarTreeState.load(s.save()).equals(s),"Ten-star masks round trip");int[] unsafe=s.masks();unsafe[2]=0;h.assertTrue(s.count(StarNode.ASSASSIN)==9,"Snapshot array cannot mutate state");var old=new CompoundTag();old.putInt("schema",2);old.putInt("lit",3);old.putInt("rank",5);h.assertFalse(StarTreeState.load(old).active(),"Changed combat entry requires deliberate reactivation, old raw NBT archived on login");h.succeed();}
    @GameTest(template="empty") public static void starHoldValidatesIndexAndTime(GameTestHelper h){var hold=new StarHold();hold.begin(StarNode.WARRIOR,8,0);h.assertFalse(hold.finish(StarNode.WARRIOR,7,24),"Index substitution rejected");h.assertFalse(hold.finish(StarNode.WARRIOR,8,23),"Short click rejected");h.assertTrue(hold.finish(StarNode.WARRIOR,8,24),"Full hold accepted");h.assertFalse(hold.finish(StarNode.WARRIOR,8,25),"Replay rejected");hold.begin(StarNode.CRYING,0,30);hold.cancel();h.assertFalse(hold.finish(StarNode.CRYING,0,60),"Release cancels");h.succeed();}
    @GameTest(template="empty") public static void departureScalesHealthWithoutFreeHealing(GameTestHelper h){var p=player(h);p.setHealth(7);h.assertTrue(SevenfoldMastery.applyStars(p,root()),"Safe activation succeeds");h.assertTrue(p.getMaxHealth()==100&&p.getHealth()==35,"Health fraction preserved on 20->100");StarAttributes.apply(p);h.assertTrue(p.getMaxHealth()==100&&p.getHealth()==35,"Reload cannot stack health");SevenfoldMastery.applyStars(p,new StarTreeState(0));h.assertTrue(p.getMaxHealth()==20&&p.getHealth()==7,"Reversible scale, no free healing");h.succeed();}
    @GameTest(template="empty") public static void separateResourcesScaleCapacityRecoveryAndPrices(GameTestHelper h){var p=new CombatPools(4,8,12,7,6).scaleTo(5);h.assertTrue(p.equals(new CombatPools(20,40,60,7,30,5))&&p.cap(Mastery.FOCUS)==20,"Absolute reserves scale; Focus layers unchanged");h.assertTrue(p.scaleTo(1).equals(new CombatPools(4,8,12,7,6)),"Scale round-trip preserves reserves");var a=new ResourceClock(0);var b=new ResourceClock(0);a.combat(0);b.combat(0);var x=new CombatPools(0,0,0,10,0);var y=x.scaleTo(5);for(int t=1;t<=20;t++){x=a.tick(x,t,true,false);y=b.tick(y,t,true,false);}h.assertTrue(y.resilience()==x.resilience()*5&&y.stamina()==x.stamina()*5&&y.might()==x.might()*5&&y.focus()==x.focus(),"Intervals unchanged, recovered points fivefold");h.succeed();}
    @GameTest(template="empty") public static void resourceRecoveryLockoutsAndFocusDecayUnchanged(GameTestHelper h){var c=new ResourceClock(0);c.hurt(0);var p=new CombatPools(0,0,0,10,0,5);for(int t=1;t<=60;t++)p=c.tick(p,t,false,false);h.assertTrue(p.resilience()==0&&p.stamina()==0,"3s and 5s lockouts unchanged");for(int t=61;t<=110;t++)p=c.tick(p,t,false,false);h.assertTrue(p.stamina()==5,"Recovery is 5 points per old increment");for(int t=111;t<=210;t++)p=c.tick(p,t,false,false);h.assertTrue(p.focus()==9,"Focus still loses only one layer after grace");h.succeed();}
    @GameTest(template="empty") public static void safeSlotMigrationAndAtomicFullBagFailure(GameTestHelper h){var p=player(h);p.getInventory().setItem(0,new ItemStack(Items.APPLE,8));p.getInventory().setItem(40,new ItemStack(Items.DIRT,30));h.assertTrue(SevenfoldMastery.applyStars(p,root()),"Can move incompatible hand items to normal bag");h.assertTrue(p.getInventory().getItem(0).isEmpty()&&p.getOffhandItem().isEmpty()&&p.getInventory().getItem(1).getCount()==8&&p.getInventory().getItem(2).getCount()==30,"No items lost");var full=player(h);for(int i=0;i<36;i++)full.getInventory().setItem(i,new ItemStack(Items.STONE,64));full.getInventory().setItem(40,new ItemStack(Items.APPLE,64));h.assertFalse(SevenfoldMastery.applyStars(full,root()),"Full bag refuses activation");h.assertTrue(!StarTreeState.of(full).active()&&full.getInventory().getItem(0).getCount()==64&&full.getOffhandItem().getCount()==64,"Failed transaction leaves all items and state intact");h.succeed();}
    @GameTest(template="empty") public static void slotPolicyRejectsVanillaSwordAndFoodButAcceptsShield(GameTestHelper h){var p=player(h);root().store(p);var slot=new Slot(p.getInventory(),0,0,0);h.assertFalse(slot.mayPlace(new ItemStack(Items.APPLE)),"Food rejected by actual Slot mixin");h.assertFalse(slot.mayPlace(new ItemStack(Items.DIAMOND_SWORD)),"Unregistered vanilla sword rejected");h.assertTrue(slot.mayPlace(new ItemStack(Items.SHIELD)),"Shields accepted");h.assertTrue(new Slot(p.getInventory(),1,0,0).mayPlace(new ItemStack(Items.APPLE)),"Ordinary inventory unaffected");h.assertTrue(p.getInventory().getFreeSlot()!=0,"Automatic pickup skips combat slot");h.succeed();}
    @GameTest(template="empty") public static void recoveryEscrowPreservesCommandInsertedItems(GameTestHelper h){var p=player(h);root().store(p);for(int i=1;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));p.getInventory().setItem(0,new ItemStack(Items.APPLE,11));CombatSlots.reconcile(p);h.assertTrue(p.getInventory().getItem(0).isEmpty()&&p.getPersistentData().getList("SevenfoldHandRecovery",10).size()==1,"Out-of-band illegal items safely escrowed");p.getInventory().setItem(9,ItemStack.EMPTY);CombatSlots.reconcile(p);h.assertTrue(p.getInventory().getItem(9).is(Items.APPLE)&&p.getInventory().getItem(9).getCount()==11&&p.getPersistentData().getList("SevenfoldHandRecovery",10).isEmpty(),"Recovery returns exact count when space appears");h.succeed();}
    @GameTest(template="empty") public static void expandedFoodPersistsAndRemainsSeparateFromMana(GameTestHelper h){var p=player(h);SevenfoldMastery.applyStars(p,root());var food=p.getFoodData();h.assertTrue(food.getFoodLevel()==100,"Food cap expands with fraction preserved");food.setFoodLevel(50);food.eat(4,.3f);h.assertTrue(food.getFoodLevel()==70&&CombatPools.of(p).mana()==100,"Food nutrition fivefold, mana independent");var t=new CompoundTag();food.addAdditionalSaveData(t);var restored=new RpgFoodData(p);restored.readAdditionalSaveData(t);restored.changeScale();h.assertTrue(restored.getFoodLevel()==70,"Loading new-scale save cannot multiply twice");h.succeed();}
    @GameTest(template="empty") public static void exhaustionConsumesFourRawFoodPoints(GameTestHelper h){var p=player(h);SevenfoldMastery.applyStars(p,root());p.getFoodData().setSaturation(20);p.getFoodData().setExhaustion(5);p.getFoodData().tick(p);h.assertTrue(p.getFoodData().getSaturationLevel()==16,"Same exhaustion threshold costs 4 instead of 1");h.succeed();}
    @GameTest(template="empty") public static void healingAndPotionCapacitiesMatchHundredHp(GameTestHelper h){var p=player(h);SevenfoldMastery.applyStars(p,root());p.setHealth(30);p.heal(4);h.assertTrue(p.getHealth()==50,"Healing potion amount scales once by five");RpgNumbers.scaledHeal(p,5);h.assertTrue(p.getHealth()==55,"Already scaled natural healing is not multiplied twice");p.addEffect(new MobEffectInstance(MobEffects.HEALTH_BOOST,200,0));h.assertTrue(p.getMaxHealth()==120,"Health boost grants20 instead of4");p.addEffect(new MobEffectInstance(MobEffects.ABSORPTION,200,0));h.assertTrue(p.getMaxAbsorption()==20&&p.getAbsorptionAmount()==20,"Absorption grants twenty points");p.setAbsorptionAmount(7);p.addEffect(new MobEffectInstance(MobEffects.ABSORPTION,300,0));h.assertTrue(p.getAbsorptionAmount()<=20,"Refreshing cannot stack absorption beyond cap");p.removeEffect(MobEffects.ABSORPTION);h.assertTrue(p.getMaxAbsorption()==0&&p.getAbsorptionAmount()==0,"Removing potion removes scaled modifier");h.succeed();}
    @GameTest(template="empty") public static void existingAbsorptionKeepsFractionAcrossDeparture(GameTestHelper h){var p=player(h);p.addEffect(new MobEffectInstance(MobEffects.ABSORPTION,200,0));p.setAbsorptionAmount(2);SevenfoldMastery.applyStars(p,root());h.assertTrue(p.getMaxAbsorption()==20&&p.getAbsorptionAmount()==10,"Existing half-spent absorption expands without a refill");SevenfoldMastery.applyStars(p,new StarTreeState(0));h.assertTrue(p.getMaxAbsorption()==4&&p.getAbsorptionAmount()==2,"Returning to old units preserves the absorption fraction");h.succeed();}
    @GameTest(template="empty") public static void savedDepartureDoesNotRefillVitalsWhenReloaded(GameTestHelper h){var p=player(h);SevenfoldMastery.applyStars(p,root());p.setHealth(58.75f);p.getFoodData().setFoodLevel(85);p.addEffect(new MobEffectInstance(MobEffects.ABSORPTION,200,0));p.setAbsorptionAmount(7);var saved=p.saveWithoutId(new CompoundTag());var loaded=player(h);loaded.load(saved);StarAttributes.apply(loaded);h.assertTrue(loaded.getMaxHealth()==100&&loaded.getHealth()==58.75f,"Transient Departure max health must load without clamping/refilling saved health");h.assertTrue(loaded.getAbsorptionAmount()==7&&loaded.getMaxAbsorption()==20,"Saved absorption cannot refill or shrink on login");h.assertTrue(loaded.getFoodData().getFoodLevel()==85&&StarTreeState.of(loaded).count(StarNode.CRYING)==10,"Food and all ten Departure stars survive login");h.succeed();}
    @GameTest(template="empty") public static void prerequisiteOnlyRevealsMainConstellations(GameTestHelper h){var s=root();for(var n:StarNode.BASES){h.assertTrue(s.visible(n)&&!s.isActivated(n)&&s.count(n)==0,"Revealed is not activated");h.assertTrue(s.canToggle(n,-1)&&!s.canToggle(n,0),"Whole constellation hold required before individual stars");h.assertTrue(s.toggle(n,0).equals(s),"Forged star request cannot bypass activation");}h.succeed();}
    @GameTest(template="empty") public static void constellationActivationDoesNotFillItsStars(GameTestHelper h){var s=root().toggle(StarNode.WARRIOR,-1);h.assertTrue(s.isActivated(StarNode.WARRIOR)&&s.count(StarNode.WARRIOR)==0&&s.path()==StarNode.WARRIOR,"Activation reserves a path without inventing ten stars");h.assertTrue(s.canToggle(StarNode.WARRIOR,0)&&!s.visible(StarNode.KNIGHT),"Children wait for active parent completion");h.succeed();}
    @GameTest(template="empty") public static void fullParentRevealsButDoesNotActivateChildren(GameTestHelper h){var s=complete(root(),StarNode.WARRIOR);h.assertTrue(s.visible(StarNode.KNIGHT)&&!s.isActivated(StarNode.KNIGHT)&&!s.canToggle(StarNode.KNIGHT,0),"Advanced constellation needs its own deliberate hold");s=s.toggle(StarNode.KNIGHT,-1);h.assertTrue(s.isActivated(StarNode.KNIGHT)&&s.count(StarNode.KNIGHT)==0&&s.profession()==WarProfession.NONE,"Activation alone never grants profession");h.succeed();}
    @GameTest(template="empty") public static void constellationDeactivationClearsDependentProgress(GameTestHelper h){var s=complete(complete(root(),StarNode.WARRIOR),StarNode.KNIGHT).toggle(StarNode.WARRIOR,-1);h.assertTrue(s.active()&&!s.isActivated(StarNode.WARRIOR)&&s.count(StarNode.WARRIOR)==0&&!s.visible(StarNode.KNIGHT)&&s.profession()==WarProfession.NONE,"Close hub clears its branch but retains Departure");h.succeed();}
    @GameTest(template="empty") public static void emptyActivatedPathsAreStillExclusive(GameTestHelper h){var s=complete(complete(root(),StarNode.WARRIOR),StarNode.BERSERKER).toggle(StarNode.ASSASSIN,-1);h.assertTrue(s.path()==StarNode.ASSASSIN&&s.count(StarNode.ASSASSIN)==0&&s.count(StarNode.WARRIOR)==0&&s.profession()==WarProfession.NONE,"Selecting empty new path clears old profession");h.assertTrue(StarTreeState.load(s.save()).equals(s),"Activated zero-star path persists");h.succeed();}
    @GameTest(template="empty") public static void schemaThreeMigrationPreservesEarnedProgress(GameTestHelper h){var s=complete(complete(root(),StarNode.WARRIOR),StarNode.KNIGHT);var old=s.save();old.putInt("schema",3);old.remove("activated");var migrated=StarTreeState.load(old);h.assertTrue(migrated.equals(s)&&migrated.profession()==WarProfession.KNIGHT,"Old earned stars migrate without losing profession");var strict=s.save();strict.putInt("activated",1);h.assertTrue(StarTreeState.load(strict).count(StarNode.WARRIOR)==0,"New schema cannot infer activation from forged star masks");h.succeed();}
    @GameTest(template="empty") public static void constellationHoldCannotBeSubstitutedByStarHold(GameTestHelper h){var s=root();h.assertFalse(s.canToggle(StarNode.WARRIOR,-2),"Only sentinel minus one denotes a constellation");var hold=new StarHold();hold.begin(StarNode.WARRIOR,-1,0);h.assertFalse(hold.finish(StarNode.WARRIOR,0,24),"Star index cannot consume constellation hold");h.assertTrue(hold.finish(StarNode.WARRIOR,-1,24),"Constellation hold has the same timing and replay protection");h.succeed();}
    @GameTest(template="empty") public static void vitalityChangesActualMaxHealthAndReverses(GameTestHelper h){var p=player(h);var s=root().toggle(StarNode.WARRIOR,-1);SevenfoldMastery.applyStars(p,s);p.setHealth(50);s=s.toggle(StarNode.WARRIOR,7);SevenfoldMastery.applyStars(p,s);h.assertTrue(p.getMaxHealth()==102&&Math.abs(p.getHealth()-51)<.01,"One Vitality star grants exactly2 final-scale maxHP and preserves fraction");s=complete(s,StarNode.WARRIOR);SevenfoldMastery.applyStars(p,s);h.assertTrue(p.getMaxHealth()==120&&Math.abs(p.getHealth()-60)<.01,"Ten Vitality stars grant20, never100");SevenfoldMastery.applyStars(p,s.toggle(StarNode.ASSASSIN,-1));h.assertTrue(p.getMaxHealth()==100&&Math.abs(p.getHealth()-50)<.01,"Switching paths removes all Vitality without healing");h.succeed();}
    @GameTest(template="empty") public static void vitalitySaveLoadKeepsExpandedHealth(GameTestHelper h){var p=player(h);SevenfoldMastery.applyStars(p,complete(root(),StarNode.WARRIOR));p.setHealth(63);var loaded=player(h);loaded.load(p.saveWithoutId(new CompoundTag()));StarAttributes.apply(loaded);h.assertTrue(loaded.getMaxHealth()==120&&loaded.getHealth()==63,"Vitality capacity loads before saved current health without refill or clamp");h.succeed();}
    @GameTest(template="empty") public static void cameraAcceleratesThenCoastsAndFreezes(GameTestHelper h){var c=new com.muxigame.sevenfold.ui.TreeCamera();c.bounds(-1000,1000,-1000,1000);c.update(639,180,640,360,.05,true);double slow=c.speed();for(int i=0;i<10;i++)c.update(639,180,640,360,.05,true);h.assertTrue(c.speed()>slow*2,"Holding the edge accelerates instead of jumping to full speed");double x=c.x();c.update(320,180,640,360,.05,true);h.assertTrue(c.x()>x&&c.speed()>0,"Releasing edge retains slight inertia");x=c.x();c.update(639,180,640,360,.05,false);h.assertTrue(c.x()==x&&c.speed()==0,"Hover/hold/menu lock prevents target drift");h.succeed();}
    @GameTest(template="empty") public static void cameraBoundsAndOutsideCursorAreStable(GameTestHelper h){var c=new com.muxigame.sevenfold.ui.TreeCamera();c.bounds(-50,50,-40,40);for(int i=0;i<200;i++)c.update(639,359,640,360,.05,true);h.assertTrue(c.x()<=50&&c.y()<=40&&c.speed()<=220.001,"Corner movement is bounded without diagonal speed boost");double x=c.x(),y=c.y();c.update(-1,180,640,360,.05,true);h.assertTrue(c.x()==x&&c.y()==y&&c.speed()==0,"Native cursor outside window never pans or gets clamped");h.succeed();}
    @GameTest(template="empty") public static void warSpecializationsLeaveOtherSectorsFree(GameTestHelper h){for(var n:new StarNode[]{StarNode.BERSERKER,StarNode.WARDEN,StarNode.KNIGHT,StarNode.BRAWLER})h.assertTrue(com.muxigame.sevenfold.ui.TreeLayout.position(n).x()<-400,"Every war specialization stays in its own left sector");double scale=com.muxigame.sevenfold.ui.TreeLayout.scale(427,240);h.assertTrue(180*scale>=40,"Compact specialization titles retain separation at GUI3");h.succeed();}
    @GameTest(template="empty") public static void openingAtEdgeWaitsForDeliberatePointerMotion(GameTestHelper h){var c=new com.muxigame.sevenfold.ui.TreeCamera();c.bounds(-500,500,-500,500);c.waitForPointerMotion();for(int i=0;i<100;i++)c.update(320,1,640,360,.05,true);h.assertTrue(c.x()==0&&c.y()==0&&c.speed()==0,"An inherited opening cursor at the edge cannot drift the tree");c.update(320,180,640,360,.05,true);c.update(320,1,640,360,.05,true);h.assertTrue(c.y()<0&&c.speed()>0,"Deliberate pointer travel arms normal edge navigation");h.succeed();}
    private static final class DamagePlayer extends FakePlayer {
        DamagePlayer(GameTestHelper h){super(h.getLevel(),new GameProfile(UUID.randomUUID(),"ScaleDamage"));try{var f=net.minecraft.server.level.ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(this,0);var net=net.minecraft.network.Connection.class.getDeclaredField("channel");net.setAccessible(true);if(net.get(connection.getConnection())==null)net.set(connection.getConnection(),new io.netty.channel.embedded.EmbeddedChannel());}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}}
        @Override public boolean isInvulnerableTo(net.minecraft.world.damagesource.DamageSource source){return false;}
        @Override public boolean canHarmPlayer(net.minecraft.world.entity.player.Player p){return true;}
    }
    @GameTest(template="empty") public static void poisonKeepsOldNonlethalFraction(GameTestHelper h){var p=new DamagePlayer(h);SevenfoldMastery.applyStars(p,root());p.setHealth(6);MobEffects.POISON.value().applyEffectTick(p,0);h.assertTrue(p.getHealth()==5,"Poison stops at five HP on the hundred-HP scale");p.invulnerableTime=0;MobEffects.POISON.value().applyEffectTick(p,0);h.assertTrue(p.getHealth()==5,"Further poison cannot kill or cross scaled floor");h.succeed();}
    @GameTest(template="empty") public static void thrownHarmingPotionRetainsCasterAndScalesOnce(GameTestHelper h){var p=new DamagePlayer(h);SevenfoldMastery.applyStars(p,root());var caster=h.spawn(EntityType.WITCH,1,2,1);MobEffects.HARM.value().applyInstantenousEffect(caster,caster,p,0,1);h.assertTrue(p.getHealth()==70,"Harming I from a real caster deals30, not6 or150");h.succeed();}
    @GameTest(template="empty") public static void starvationAndNaturalRegenerationDoNotDoubleScale(GameTestHelper h){var p=new DamagePlayer(h);SevenfoldMastery.applyStars(p,root());p.getFoodData().setFoodLevel(0);p.getFoodData().setSaturation(0);for(int i=0;i<80;i++)p.getFoodData().tick(p);h.assertTrue(p.getHealth()==95,"Starvation is five HP, never twenty-five");p.setHealth(50);p.getFoodData().setFoodLevel(100);p.getFoodData().setSaturation(30);p.getFoodData().setExhaustion(0);for(int i=0;i<10;i++)p.getFoodData().tick(p);h.assertTrue(p.getHealth()==55,"Fast natural heal restores five HP once");h.succeed();}
    @GameTest(template="empty") public static void professionPaymentsScaleButIncompleteProfessionDoesNothing(GameTestHelper h){var p=player(h);var s=complete(root(),StarNode.WARRIOR).toggle(StarNode.BERSERKER,-1);for(int i=0;i<9;i++)s=s.toggle(StarNode.BERSERKER,i);SevenfoldMastery.applyStars(p,s);var denied=new com.muxigame.zaluokeforging.api.WeaponPenaltyEvent(p,com.muxigame.zaluokeforging.api.WeaponPenaltyEvent.Penalty.GIANT_HANDLING);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(denied);h.assertTrue(!denied.waived()&&CombatPools.of(p).might()==100,"Incomplete profession has no effect or price");SevenfoldMastery.applyStars(p,s.toggle(StarNode.BERSERKER,9));var accepted=new com.muxigame.zaluokeforging.api.WeaponPenaltyEvent(p,com.muxigame.zaluokeforging.api.WeaponPenaltyEvent.Penalty.GIANT_HANDLING);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(accepted);h.assertTrue(accepted.waived()&&CombatPools.of(p).might()==90,"Same two old units cost ten new units");h.succeed();}

    @GameTest(template="empty") public static void realNeedsDamageRemainsInBodyConditionUnits(GameTestHelper h){
        if(!net.neoforged.fml.ModList.get().isLoaded("real_needs")){h.succeed();return;}
        var old=new DamagePlayer(h);var scaled=new DamagePlayer(h);SevenfoldMastery.applyStars(scaled,root());
        old.getRandom().setSeed(18471);scaled.getRandom().setSeed(18471);
        old.hurt(old.damageSources().fall(),2);scaled.hurt(scaled.damageSources().fall(),2);
        h.assertTrue(old.getPersistentData().getCompound("RealNeeds").getCompound("body").equals(scaled.getPersistentData().getCompound("RealNeeds").getCompound("body")),"Fivefold HP damage must not cause fivefold injury to independent body-condition scores");
        h.assertTrue(old.getHealth()==18&&scaled.getHealth()==90,"Damage changes scale, not body-condition gameplay");h.succeed();
    }

}
